function loadClaims() {
  try { const stored = JSON.parse(localStorage.getItem(STORAGE_KEY)); if (Array.isArray(stored) && stored.length) return stored; } catch (e) { /* fallback */ }
  return defaultClaims.map(c => ({ ...c, evidence: c.evidence ? [...c.evidence] : [], audit: c.audit ? [...c.audit] : [] }));
}
function persistClaims() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(claims)); } catch (e) { /* Algunos iframes de Streamlit bloquean el almacenamiento local. */ } }
function escapeHtml(value = '') { return String(value).replace(/[&<>'"]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#039;', '"':'&quot;' }[c])); }
function initials(name) { return name.split(' ').map(part => part[0]).slice(0, 2).join('').toUpperCase(); }
function nowTime() { return new Date().toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' }); }
function showToast(title, detail = '') { const region = document.getElementById('toast-region'); const node = document.createElement('div'); node.className = 'toast'; node.innerHTML = `<strong>${escapeHtml(title)}</strong>${escapeHtml(detail)}`; region.appendChild(node); setTimeout(() => node.remove(), 3600); }
function statusPill(claim) { return `<span class="pill ${claim.statusClass}">${escapeHtml(claim.status)}</span>`; }
function confidenceHTML(value) { const cls = value < .7 ? 'low' : value >= .85 ? 'high' : ''; return `<span class="confidence ${cls}">${Math.round(value * 100)}%</span>`; }

function render() {
  const container = document.getElementById('view-container');
  const views = { overview: renderOverview, claims: renderClaims, faq: renderFaq, orders: renderOrders, sources: renderSources, reports: renderReports, sprints: renderSprints, settings: renderSettings };
  container.innerHTML = views[currentView]();
  document.querySelectorAll('.nav-item[data-view]').forEach(btn => btn.classList.toggle('active', btn.dataset.view === currentView));
  const current = document.querySelector(`.nav-item[data-view="${currentView}"]`);
  document.getElementById('breadcrumb-current').textContent = current ? current.querySelector('span:not(.nav-icon):not(.nav-count)')?.textContent || 'Resumen' : 'Resumen';
  bindViewEvents();
}

