function renderClaimsTable(rows) {
  if (!rows.length) return '<div class="empty-state"><strong>No hay casos con este filtro</strong><span>Cuando aparezcan nuevos reclamos, los verás aquí.</span></div>';
  return `<div class="table-wrap"><table><thead><tr><th>Reclamo</th><th>Categoría sugerida</th><th>Confianza</th><th>Estado</th><th>Creado</th></tr></thead><tbody>${rows.map(c => `<tr data-claim-id="${c.id}"><td><div class="claim-cell"><div class="claim-avatar ${c.avatar}">${escapeHtml(c.initials)}</div><div><span class="claim-ref">${c.id}</span><span class="claim-customer">${escapeHtml(c.customer)}</span></div></div></td><td>${escapeHtml(c.category)}</td><td>${confidenceHTML(c.confidence)}</td><td>${statusPill(c)}</td><td>${escapeHtml(c.created)}</td></tr>`).join('')}</tbody></table></div>`;
}

function renderClaims() {
  const filtered = currentFilter === 'Todos' ? claims : claims.filter(c => c.status === currentFilter);
  return `<div class="view-header"><div><span class="eyebrow accent">Atención / Operaciones</span><h1>Bandeja de reclamos</h1><p>Clasificación, evidencia y revisión humana en un solo lugar.</p></div><button class="button primary" data-action="new-claim">+ Registrar reclamo</button></div>
    <div class="filter-row"><input class="filter-search" id="claim-search" placeholder="Buscar por cliente, ID o pedido"/><select class="select-control" id="status-filter"><option>Todos</option><option>Nuevo</option><option>En curso</option><option>Pendiente de revisión</option><option>Escalado</option><option>Aprobado</option><option>Resuelto</option></select><select class="select-control"><option>Más recientes</option><option>Más antiguos</option><option>Mayor confianza</option></select><span class="filter-spacer"></span><span class="eyebrow" style="text-transform:none;letter-spacing:0">${filtered.length} casos</span></div>
    <div class="view-tabs"><button class="view-tab active">Todos los casos</button><button class="view-tab">Mis asignados <span class="nav-count">6</span></button><button class="view-tab">Escalados <span class="nav-count">2</span></button></div>
    <section class="panel">${renderClaimsTable(filtered)}<div class="table-footer"><span>Actualizado hace 2 min · La clasificación se revisa con umbral 0,70</span><div class="pagination"><button class="active">1</button><button>2</button><button>3</button></div></div></section>`;
}

function renderFaq() {
  const active = faqItems.find(f => f.id === currentFaqId) || faqItems[0];
  const answer = active.answer ? `<div class="answer-copy">${escapeHtml(active.answer)}</div><div class="source-chip"><i>⌁</i>${escapeHtml(active.source)}</div>` : `<div class="answer-note">No hay evidencia suficiente para responder con seguridad. Este caso debe pasar a revisión de un agente.</div>`;
  return `<div class="view-header"><div><span class="eyebrow accent">Conocimiento / Respuestas validadas</span><h1>Preguntas frecuentes</h1><p>Respuestas directas para consultas simples, sin usar generación automática.</p></div><span class="pill approved">Base validada · ${faqItems.length} entradas</span></div><div class="faq-layout"><div><input class="faq-search" id="faq-search" placeholder="Busca una pregunta o palabra clave"/>${faqItems.map(f => `<article class="faq-card ${f.id === currentFaqId ? 'selected' : ''}" data-faq-id="${f.id}"><span class="faq-tag">${escapeHtml(f.tag)}</span><h3>${escapeHtml(f.question)}</h3><p>${f.answer ? 'Respuesta validada disponible' : 'Revisión requerida antes de responder'}</p></article>`).join('')}</div><section class="panel answer-panel"><span class="eyebrow accent">Respuesta seleccionada</span><h2>${escapeHtml(active.question)}</h2>${answer}<div style="margin-top:20px;display:flex;gap:7px"><button class="button primary small" data-action="use-faq" ${active.answer ? '' : 'disabled'}>Usar en un caso</button><button class="button ghost small" data-action="review-faq">Enviar a revisión</button></div></section></div>`;
}

function renderOrders() { return `<div class="view-header"><div><span class="eyebrow accent">Atención / Consulta</span><h1>Consultar pedido</h1><p>Consulta de pedidos simulados para responder con información verificable.</p></div></div><div class="order-lookup"><section class="lookup-card"><span class="eyebrow">Identificador de pedido</span><h2 style="font-size:16px;letter-spacing:-.03em;color:#2d4558;margin:5px 0 0">¿En qué estado está tu pedido?</h2><form class="lookup-form" id="order-form"><input id="order-input" placeholder="DG4-2026-1042" autocomplete="off"/><button class="button primary" type="submit">Consultar <span>→</span></button></form><div id="order-result"></div></section></div>`; }
