function renderReports() { return `<div class="view-header"><div><span class="eyebrow accent">Evaluación / Sprint 2</span><h1>Reporte reproducible</h1><p>Resultados de la configuración base · Dataset de 120 casos etiquetados.</p></div><button class="button ghost" data-action="export-report">Exportar reporte</button></div><div class="report-grid"><div class="metric-panel"><span class="metric-label">Clasificación · F1 macro</span><span class="metric-number">0,89</span><div class="metric-sub">106 de 120 casos correctamente clasificados</div><div class="progress-bar"><span style="width:89%"></span></div></div><div class="metric-panel"><span class="metric-label">Recuperación · Recall@3</span><span class="metric-number">0,86</span><div class="metric-sub">Evidencia pertinente en los tres primeros fragmentos</div><div class="progress-bar teal"><span style="width:86%"></span></div></div><div class="metric-panel"><span class="metric-label">Abstención segura</span><span class="metric-number">92<span style="font-size:13px">%</span></span><div class="metric-sub">Casos sin evidencia enviados a revisión</div><div class="progress-bar amber"><span style="width:92%"></span></div></div></div><div class="grid-1-1"><section class="panel"><div class="panel-header"><div><h2>Indicadores del prototipo</h2><p>Medidos con la misma configuración</p></div><span class="eyebrow">22 oct 2026</span></div><div class="table-wrap"><table class="report-table"><thead><tr><th>Métrica</th><th>Resultado</th><th>Objetivo</th><th>Estado</th></tr></thead><tbody><tr><td>Fidelidad de respuesta</td><td><div class="bar-inline"><div class="bar"><span style="width:91%"></span></div><span>0,91</span></div></td><td>≥ 0,85</td><td><span class="pill approved">Cumple</span></td></tr><tr><td>Precisión de enrutamiento</td><td><div class="bar-inline"><div class="bar"><span style="width:88%"></span></div><span>0,88</span></div></td><td>≥ 0,80</td><td><span class="pill approved">Cumple</span></td></tr><tr><td>Latencia p95</td><td>1,8 s</td><td>≤ 2,5 s</td><td><span class="pill approved">Cumple</span></td></tr><tr><td>Abstención sin evidencia</td><td>0,92</td><td>≥ 0,90</td><td><span class="pill approved">Cumple</span></td></tr></tbody></table></div></section><section class="panel"><div class="panel-header"><div><h2>Tiempo de atención</h2><p>Comparación por muestra de 30 casos</p></div></div><div style="padding:20px 21px"><div style="display:flex;justify-content:space-between;align-items:end;margin-bottom:17px"><div><span class="eyebrow">Manual</span><strong style="display:block;color:#607383;font:21px var(--mono);margin-top:4px">11m 42s</strong></div><div style="font-size:18px;color:#a6b2ba">→</div><div style="text-align:right"><span class="eyebrow">Asistido</span><strong style="display:block;color:#188e7f;font:21px var(--mono);margin-top:4px">4m 18s</strong></div></div><div class="progress-bar" style="height:9px"><span style="width:37%;background:#74b8ad"></span></div><p style="color:#8d9ba5;font-size:9px;margin:10px 0 0">Reducción media de <strong style="color:#198f80">63%</strong> con revisión humana obligatoria.</p></div></section></div>`; }

